insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_30_v1'
from (values
('127.172.d.4',3,'A print shop employee uses design software, email, and a file-transfer site to send proofs to customers. These are:','["Technology applications", "Press plates", "Hand tools", "Safety signs"]'::jsonb,0,'Technology applications.','original'),
('127.172.d.4',4,'Uploading a customer''s artwork through a secure web portal for a print job shows the use of:','["Paper cutting", "Technology to exchange files", "Ink mixing", "Die stamping"]'::jsonb,1,'Technology applications.','original'),
('127.172.d.9',3,'A press operator who learns the shortcuts on the digital press controller is applying technical skills for:','["Confusion", "Waste", "Efficiency", "Delay"]'::jsonb,2,'Technical skills.','original'),
('127.172.d.9',4,'Saving job settings as a preset on a digital press helps a shop:','["Skip proofing", "Print slower", "Waste more paper", "Repeat jobs faster with fewer setup errors"]'::jsonb,3,'Technical skills.','original'),
('127.172.d.11',3,'Learning about Gutenberg''s movable-type press is part of researching the:','["History of the printing and imaging field", "History of metals", "Future of weather", "Rules of sports"]'::jsonb,0,'History of printing.','original'),
('127.172.d.11',4,'The invention of offset lithography in the early 1900s changed printing by allowing:','["Only black ink", "Fast, high-volume printing with consistent quality", "Hand-copied books", "Wood-block carving only"]'::jsonb,1,'History of printing.','original'),
('127.172.d.1.A',3,'A print shop employee writes a clear job ticket with correct spelling and details. This applies:','["Mixing skills", "Binding skills", "English language arts skills", "Welding skills"]'::jsonb,2,'ELA.','original'),
('127.172.d.1.A',4,'Proofreading a customer''s flyer before it goes to press mainly prevents:','["Paper curl", "Faster ink drying", "Machine noise", "Costly errors in the finished job"]'::jsonb,3,'ELA in industry.','original'),
('127.172.d.1.B',3,'A print job needs 2,500 flyers. They print 4 flyers per sheet. How many sheets are needed?','["625", "600", "10,000", "650"]'::jsonb,0,'2500 / 4 = 625.','original'),
('127.172.d.1.B',4,'A press prints 120 sheets per minute. How many sheets does it print in 15 minutes?','["1,500", "1,800", "1,200", "2,100"]'::jsonb,1,'120 x 15 = 1800.','original'),
('127.172.d.2.A',3,'A shop worker explains bleed and trim to a first-time customer in plain words. This is adapting language to the:','["Ink", "Press", "Audience", "Cutter"]'::jsonb,2,'Adapt language.','original'),
('127.172.d.2.A',4,'A technical email to a prepress department uses industry terms, while a customer email uses plain terms. This reflects different:','["Ink colors", "Press speeds", "Paper sizes", "Audience and purpose"]'::jsonb,3,'Adapt language.','original'),
('127.172.d.2.B',3,'Sorting job tickets by due date is:','["Organizing information", "Mixing ink", "Plate making", "Trimming paper"]'::jsonb,0,'Organize information.','original'),
('127.172.d.2.B',4,'Preparing a written quote with materials, labor, and delivery listed in order helps customers:','["Get confused", "Understand the cost clearly", "Avoid reading it", "Delay approval"]'::jsonb,1,'Organize.','original'),
('127.172.d.2.C',3,'A press operator reports that the density readings are drifting lighter. This is:','["Cutting paper", "Cleaning rollers", "Interpreting and communicating data", "Loading ink"]'::jsonb,2,'Interpret information.','original'),
('127.172.d.2.C',4,'A shop foreman reads a waste report and tells the team that makeready sheets are too high. This communicates:','["A guess", "A rumor", "A joke", "A data-based observation"]'::jsonb,3,'Communicate data.','original'),
('127.172.d.2.D',3,'Showing a customer a printed sample and explaining the finish options is a:','["Formal presentation", "Press check", "Break", "Casual joke"]'::jsonb,0,'Formal presentation.','original'),
('127.172.d.2.D',4,'Giving a quick shift update to coworkers about a press problem is a(n):','["Keynote", "Informal presentation", "Press release", "Awards speech"]'::jsonb,1,'Informal presentation.','original'),
('127.172.d.2.E',3,'A prepress worker repeats back a customer''s color request to confirm it. This is:','["Ignoring", "Interrupting", "Active listening", "Daydreaming"]'::jsonb,2,'Active listening.','original'),
('127.172.d.2.F',3,'A shop supervisor works with employees and customers from many backgrounds, which requires:','["Teasing", "Stereotypes", "Silence", "Respectful, clear communication"]'::jsonb,3,'Diverse groups.','original'),
('127.172.d.2.E',4,'Asking a customer to clarify "make it pop" before changing a design is a form of:','["Active listening", "Guessing", "Delaying", "Arguing"]'::jsonb,0,'Active listening.','original'),
('127.172.d.2.F',4,'A print shop with a multilingual team can better serve:','["Only one market", "A wider range of customers", "Fewer customers", "No one"]'::jsonb,1,'Diverse groups.','original'),
('127.172.d.2.G',3,'Thanking a customer and fixing a printing error quickly builds the shop''s:','["Overhead", "Waste", "Public relations and reputation", "Ink supply"]'::jsonb,2,'PR skills.','original'),
('127.172.d.2.G',4,'A customer complains that the colors look different from the proof. A strong PR response is to:','["Blame them", "Argue", "Ignore it", "Listen, explain, and offer a fix"]'::jsonb,3,'PR skills.','original'),
('127.172.d.3.A',3,'A team compares two paper stocks by cost, finish, and durability before choosing. This is:','["Critical thinking", "Guessing", "Habit", "Coin flipping"]'::jsonb,0,'Critical thinking.','original'),
('127.172.d.3.A',4,'Testing a sample print on two papers before a large run is an example of using:','["A rumor", "Evidence to make a decision", "A hunch", "Luck"]'::jsonb,1,'Critical thinking.','original'),
('127.172.d.3.B',3,'Two workers disagree about the press schedule. A good interpersonal skill is to:','["Blame", "Yell", "Listen and compromise", "Quit"]'::jsonb,2,'Interpersonal skills.','original'),
('127.172.d.3.B',4,'When a rush order conflicts with a scheduled job, a team solves it best by:','["Ignoring the rush", "Taking sides", "Hiding the order", "Discussing priorities and agreeing on a plan"]'::jsonb,3,'Group problem solving.','original'),
('127.172.d.5.A',3,'Wearing safety glasses and gloves around the paper cutter is:','["Following personal safety rules", "Slowing work", "A fashion choice", "Optional"]'::jsonb,0,'Safety.','original'),
('127.172.d.5.A',4,'Before servicing a press, a worker should use a lockout/tagout procedure to:','["Save energy", "Prevent the machine from starting unexpectedly", "Speed up work", "Reduce noise"]'::jsonb,1,'Workplace safety.','original'),
('127.172.d.5.B',3,'If a chemical splashes in a coworker''s eyes, the first step is to:','["Ignore it", "Wait", "Use an eyewash station and get help", "Wipe with ink rags"]'::jsonb,2,'Emergency procedures.','original'),
('127.172.d.5.B',4,'A shop''s safety data sheets (SDS) are kept so workers can:','["Find ink prices", "Learn press speeds", "Order lunch", "Find hazard and first-aid information for chemicals"]'::jsonb,3,'Emergency procedures.','original'),
('127.172.d.6.A',3,'Telling a coworker clearly when a press needs maintenance is using:','["Communication skills", "Silence", "Guesswork", "Rumors"]'::jsonb,0,'Communication.','original'),
('127.172.d.6.A',4,'Writing a shift handoff note for the next press crew helps by:','["Confusing the crew", "Passing on important information", "Hiding errors", "Wasting time"]'::jsonb,1,'Communication.','original'),
('127.172.d.6.B',3,'Press, bindery, and prepress staff working together to finish a rush order shows:','["Isolation", "Rivalry", "Teamwork", "Delay"]'::jsonb,2,'Teamwork.','original'),
('127.172.d.6.B',4,'A good way to manage a conflict between two crews over equipment is to:','["Argue", "Blame management", "Hide equipment", "Meet and agree on a shared schedule"]'::jsonb,3,'Conflict management.','original'),
('127.172.d.6.C',3,'A well-run shop meeting should have an agenda and:','["Stay on topic", "Run all day", "Exclude input", "Skip decisions"]'::jsonb,0,'Meetings.','original'),
('127.172.d.6.C',4,'Recording who is responsible for each action item after a meeting keeps the team:','["Unclear", "Accountable", "Isolated", "Delayed"]'::jsonb,1,'Meetings.','original'),
('127.172.d.6.D',3,'A veteran press operator teaching a new hire to load paper is:','["Hiding skills", "Delaying", "Mentoring", "Competing"]'::jsonb,2,'Mentoring.','original'),
('127.172.d.6.D',4,'Good mentoring skills include:','["Silence", "Impatience", "Criticism only", "Patience, clear instructions, and encouragement"]'::jsonb,3,'Mentoring skills.','original'),
('127.172.d.7.A',3,'Telling the truth about a delayed job instead of hiding it is:','["Ethical conduct", "Optional", "Unprofessional", "A mistake"]'::jsonb,0,'Ethical conduct.','original'),
('127.172.d.7.A',4,'Keeping a client''s unpublished design confidential is:','["Unfair", "Ethical professional behavior", "A technical error", "Optional"]'::jsonb,1,'Ethics.','original'),
('127.172.d.7.B',3,'Copying and printing a magazine''s photograph for a customer without permission raises:','["A color issue", "A press issue", "A copyright issue", "A paper issue"]'::jsonb,2,'Copyright.','original'),
('127.172.d.7.B',4,'Fair use allows limited reproduction of copyrighted work for purposes such as:','["Mass advertising", "Any reuse", "Resale", "Criticism, teaching, or news reporting"]'::jsonb,3,'Fair use.','original'),
('127.172.d.7.C',3,'A Creative Commons license lets creators:','["Specify how others may use their work", "Hide their work", "Ban all use", "Remove all rights"]'::jsonb,0,'Creative Commons.','original'),
('127.172.d.7.C',4,'A photographer''s Creative Commons license that requires attribution means users must:','["Change the photo''s name", "Credit the photographer", "Delete the photo", "Pay a fee always"]'::jsonb,1,'Creative Commons licensing.','original'),
('127.172.d.8.A',3,'A portfolio of printed samples helps a graduate:','["Hide work", "Avoid interviews", "Show skills to employers", "Skip training"]'::jsonb,2,'Portfolio.','original'),
('127.172.d.8.A',4,'Including a variety of print products, such as brochures and business cards, in a portfolio shows:','["Lack of focus", "Confusion", "Limited ability", "Range of skills"]'::jsonb,3,'Portfolio.','original'),
('127.172.d.8.B',3,'Comparing pay, benefits, and training from two print shops is:','["Evaluating employment opportunities", "Daydreaming", "Guessing", "Gambling"]'::jsonb,0,'Compare employment.','original'),
('127.172.d.8.B',4,'A job that offers apprenticeship training in press operation may be valuable for:','["Skipping school", "Long-term career growth", "Avoiding learning", "Immediate retirement"]'::jsonb,1,'Evaluate opportunities.','original'),
('127.172.d.8.C',3,'Opening a small custom screen-printing business is an example of:','["Unemployment", "Job loss", "Entrepreneurship", "Retirement"]'::jsonb,2,'Entrepreneurship.','original'),
('127.172.d.8.C',4,'A print entrepreneur needs to plan for expenses such as:','["Only decorations", "Nothing", "Only fun", "Equipment, supplies, and marketing"]'::jsonb,3,'Entrepreneurship.','original'),
('127.172.d.10.A',3,'Offset lithography, digital printing, and screen printing are examples of:','["Printing systems", "Fonts", "Paper types", "Ink colors"]'::jsonb,0,'Printing systems.','original'),
('127.172.d.10.A',4,'A shop with a short-run, quick-turn job for 50 copies would likely use:','["Large offset press", "Digital printing", "Gravure", "Letterpress"]'::jsonb,1,'Printing systems.','original'),
('127.172.d.10.B',3,'The usual stages of producing a printed product are prepress, press, and:','["Marketing only", "Cooking", "Finishing (postpress)", "Recycling only"]'::jsonb,2,'Production processes.','original')
